document.addEventListener("DOMContentLoaded",function(){const e=document.querySelector(".header__language");e&&e.addEventListener("click",function(){e.classList.toggle("open")});const t=document.querySelector(".header__languages");t&&t.addEventListener("click",function(t){t.stopPropagation(),t.target.classList.contains("header__languages")&&e.classList.remove("open")});const n=document.querySelector(".header__burger-btn"),o=document.querySelector(".header__burger");n&&o&&n.addEventListener("click",function(){o.classList.toggle("open")})});